-- Flow Planner: one update after migrations 001–007. Also safe if 008 is already applied.
-- Generated by npm run db:bundle. Does not recreate tables or remove data.
begin;

-- 008_task_undo.sql
-- Atomic undo: reject stale snapshots rather than overwrite another device's edits.

create or replace function public.undo_task_changes(changes jsonb) returns jsonb
language plpgsql security invoker set search_path = '' as $$
declare item jsonb; actual jsonb; expected public.tasks; result jsonb; saved jsonb; deleted uuid[];
begin
  if changes is null or jsonb_typeof(changes)<>'array' or jsonb_array_length(changes) not between 1 and 50000 then raise exception 'Invalid undo batch'; end if;
  if (select count(*) <> count(distinct value->>'id') from jsonb_array_elements(changes)) then raise exception 'Duplicate undo task'; end if;
  perform id from public.tasks where id in (select (value->>'id')::uuid from jsonb_array_elements(changes)) order by id for update;
  for item in select value from jsonb_array_elements(changes) loop
    if item->>'id' is null or not (item ? 'before' and item ? 'after') then raise exception 'Invalid undo task'; end if;
    select to_jsonb(t) into actual from public.tasks t where id=(item->>'id')::uuid;
    if item->'after' = 'null'::jsonb then
      if actual is not null then raise exception 'Task changed; undo cancelled'; end if;
    else
      expected := jsonb_populate_record(null::public.tasks,item->'after');
      if expected.id is distinct from (item->>'id')::uuid or actual is distinct from to_jsonb(expected) then raise exception 'Task changed; undo cancelled'; end if;
    end if;
    if item->'before' <> 'null'::jsonb and (item->'before'->>'id')::uuid is distinct from (item->>'id')::uuid then raise exception 'Invalid undo identity'; end if;
  end loop;
  select coalesce(jsonb_agg(value->'before') filter(where value->'before'<>'null'::jsonb),'[]'::jsonb), coalesce(array_agg((value->>'id')::uuid) filter(where value->'before'='null'::jsonb),'{}'::uuid[]) into saved,deleted from jsonb_array_elements(changes);
  result := public.apply_task_changes(saved,deleted);
  -- A concurrently inserted series occurrence must not silently swallow restoration.
  for item in select value from jsonb_array_elements(changes) where value->'before'<>'null'::jsonb loop
    expected := jsonb_populate_record(null::public.tasks,item->'before');
    select to_jsonb(t) into actual from public.tasks t where id=expected.id;
    if (actual-'calendar_revision'-'calendar_updated_at') is distinct from (to_jsonb(expected)-'calendar_revision'-'calendar_updated_at') then raise exception 'Unable to restore task; undo cancelled'; end if;
  end loop;
  return result;
end;
$$;
revoke all on function public.undo_task_changes(jsonb) from public,anon;
grant execute on function public.undo_task_changes(jsonb) to authenticated;

-- 009_checked_task_writes.sql
create or replace function public.planner_capabilities() returns jsonb language sql stable security invoker set search_path='' as $$ select '{"checked_task_writes":true}'::jsonb $$;
create or replace function public.apply_task_changes_checked(changes jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
begin
  if changes is null or jsonb_typeof(changes)<>'array' or jsonb_array_length(changes) not between 1 and 50000 then raise exception 'Invalid task changes'; end if;
  return public.undo_task_changes((select jsonb_agg(jsonb_build_object('id',value->'id','before',value->'after','after',value->'before')) from jsonb_array_elements(changes)));
end;
$$;
revoke all on function public.planner_capabilities() from public,anon;
revoke all on function public.apply_task_changes_checked(jsonb) from public,anon;
grant execute on function public.planner_capabilities() to authenticated;
grant execute on function public.apply_task_changes_checked(jsonb) to authenticated;

commit;
